style.css:
@-moz-document domain("open.spotify.com") {
/* === Floral Background === */
  html,
  body {
    background: url("https://i.pinimg.com/736x/13/c8/64/13c864beba67f53294da6d2934397451.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  .Root__main-view,
  .main-view-container,
  .main-nowPlayingBar-nowPlayingBar {
    background-color: transparent !important;
  }

  /* === Home Icon === */
  a[href="/"] svg path {
    fill: #91412d !important;
  }

  /* === Spotify Logo === */
  .main-topBar-logo svg path {
    fill: #91412d !important;
  }

  /* === Play/Pause Button === */
  .player-controls__buttons button[aria-label="Play"],
  .player-controls__buttons button[aria-label="Pause"] {
    background-color: #91412d !important;
    color: white !important;
    border-radius: 50% !important;
  }

  /* === Progress Bar === */
  .progress-bar__fg {
    background-color: #91412d !important;
    height: 4px !important;
  }

  .progress-bar__bg {
    background-color: rgba(145, 65, 45, 0.3) !important;
  }

  /* === Now Playing Track Title === */
  .now-playing-bar__left div span:first-child {
    color: #91412d !important;
    font-weight: bold !important;
  }
}
